<?php require __DIR__.'/config.php';$u=require_login();$b=require_business();if($b['type']!=='hotel')redirect('index.php');$pdo=db();$defaults=[['Room Service','🍽️'],['Restaurant','🍴'],['Bar','🍸'],['Housekeeping','🧹'],['Laundry','🧺'],['Maintenance','🛠️'],['Spa','🧖'],['Transport','🚕'],['Reception','🛎️']];$count=$pdo->prepare("SELECT COUNT(*) FROM business_services WHERE business_id=?");$count->execute([$b['id']]);if(!$count->fetchColumn()){foreach($defaults as $d){$s=$pdo->prepare("INSERT IGNORE INTO business_services(business_id,name,icon,enabled) VALUES(?,?,?,1)");$s->execute([$b['id'],$d[0],$d[1]]);}}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$a=$_POST['action']??'';if($a==='outlet'){$s=$pdo->prepare("INSERT INTO outlets(business_id,name,type,created_at) VALUES(?,?,?,NOW())");$s->execute([$b['id'],trim($_POST['name']),$_POST['type']]);flash('Outlet created.');}elseif($a==='service'){if(isset($_POST['enabled']) && (string)$_POST['enabled']==='1' && ($err=plan_limit_error((int)$b['id'],'services')))throw new RuntimeException($err);$s=$pdo->prepare("UPDATE business_services SET enabled=? WHERE id=? AND business_id=?");$s->execute([isset($_POST['enabled'])?1:0,(int)$_POST['id'],$b['id']]);flash('Service updated.');}elseif($a==='room'){ $start=trim($_POST['start']);$n=max(1,min(300,(int)$_POST['count']));$existing=(int)$pdo->query("SELECT COUNT(*) FROM locations WHERE business_id=".(int)$b['id']." AND type='room' AND status='active'")->fetchColumn();if($err=plan_limit_error((int)$b['id'],'rooms',$n))throw new RuntimeException($err);for($i=0;$i<$n;$i++){$name='Room '.($start+$i);$s=$pdo->prepare("INSERT INTO locations(business_id,type,name,created_at) VALUES(?,?,?,NOW())");$s->execute([$b['id'],'room',$name]);$lid=$pdo->lastInsertId();$token=random_token();$s=$pdo->prepare("INSERT INTO qr_codes(business_id,location_id,token,label,created_at) VALUES(?,?,?,?,NOW())");$s->execute([$b['id'],$lid,$token,$name]);}flash($n.' rooms and QR codes created.');}}catch(Throwable $e){flash($e->getMessage(),'error');}redirect('hotel.php');}$out=$pdo->prepare("SELECT * FROM outlets WHERE business_id=? ORDER BY id DESC");$out->execute([$b['id']]);$out=$out->fetchAll();$rooms=$pdo->prepare("SELECT l.*,q.id qr_id FROM locations l LEFT JOIN qr_codes q ON q.location_id=l.id AND q.status='active' WHERE l.business_id=? AND l.type='room' ORDER BY l.id DESC LIMIT 100");$rooms->execute([$b['id']]);$rooms=$rooms->fetchAll();$sv=$pdo->prepare("SELECT * FROM business_services WHERE business_id=? ORDER BY id");$sv->execute([$b['id']]);$sv=$sv->fetchAll();include __DIR__.'/app/layout_top.php';?><div class="page-head"><div><div class="eyebrow">Hotel</div><h1>Guest services</h1><p>Configure what guests see after scanning a room QR.</p></div></div><div class="panel"><h3>Guest service hub</h3><?php foreach($sv as $x):?><div class="row"><div><b><?=e($x['icon'])?> <?=e($x['name'])?></b><div class="small muted">Visible to guests when enabled.</div></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="service"><input type="hidden" name="id" value="<?=$x['id']?>"><input type="hidden" name="enabled" value="<?=$x['enabled']?'':'1'?>"><button class="btn <?= $x['enabled']?'gold':''?>"><?= $x['enabled']?'Enabled':'Disabled'?></button></form></div><?php endforeach;?></div><div class="panel"><h3>Hotel outlets</h3><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="outlet"><input name="name" placeholder="Rooftop Bar" required><select name="type"><option value="restaurant">Restaurant</option><option value="bar">Bar</option><option value="pool">Pool</option><option value="room_service">Room Service</option><option value="other">Other</option></select><button class="btn gold">Add outlet</button></form><?php foreach($out as $x):?><div class="row"><b><?=e($x['name'])?></b><span class="badge"><?=e(strtoupper($x['type']))?></span></div><?php endforeach;?></div><div class="panel"><h3>Rooms + QR</h3><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="room"><input name="start" value="101" required><input type="number" name="count" value="10" min="1" max="300"><button class="btn gold">Create rooms</button></form><?php foreach($rooms as $r):?><div class="row"><div><b><?=e($r['name'])?></b><div class="small muted">Guest service QR</div></div><?php if($r['qr_id']):?><a class="btn" href="qr-card.php?id=<?=$r['qr_id']?>">QR</a><?php endif;?></div><?php endforeach;?></div><?php include __DIR__.'/app/layout_bottom.php';
